<?php require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/db.php';$p=$pdo->query("SELECT * FROM profile LIMIT 1")->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare("UPDATE profile SET headline=?,intro=?,about=?,email=?,phone=?,location=? WHERE id=?");$q->execute([$_POST['headline'],$_POST['intro'],$_POST['about'],$_POST['email'],$_POST['phone'],$_POST['location'],$p['id']]);$p=$pdo->query("SELECT * FROM profile LIMIT 1")->fetch();$msg='Profile updated.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-wrap"><a class="text-link" href="dashboard.php">← Dashboard</a><h1>Profile & <em>CV.</em></h1><?php if(!empty($msg)):?><p class="notice"><?=$msg?></p><?php endif;?><form class="form-card" method="post"><?php foreach(['headline'=>'Professional headline','intro'=>'Short intro on homepage','about'=>'About me','email'=>'Email','phone'=>'Phone','location'=>'Location'] as $k=>$label):?><label><?=$label?></label><?php if(in_array($k,['intro','about'])):?><textarea name="<?=$k?>" rows="4"><?=htmlspecialchars($p[$k])?></textarea><?php else:?><input name="<?=$k?>" value="<?=htmlspecialchars($p[$k])?>"><?php endif;?><?php endforeach;?><button>Save profile</button></form></div></body></html>